typedef float rational_t;

class stringx
{
  char *chars;
  void *my_buf;
};

class vector3d
{
  float x, y, z;
};

class region_node;
class ai_goal;

class ai_interface
{
public:
  bool play_animation(const stringx &, int, unsigned short, int *, rational_t *,
                      rational_t *, int *);
};

class entity
{
public:
  const vector3d &get_abs_position() const;
  region_node *get_primary_region() const;
};

bool in_world(const vector3d &, rational_t, const vector3d &, region_node *,
              vector3d &, bool = false);
extern const vector3d ZEROVEC;

class ai_action
{
public:
  virtual ~ai_action();
  virtual bool frame_advance(float) = 0;
  virtual void going_out_of_service();
  virtual void going_into_service();

  ai_interface *get_ai_interface() const;
  entity *get_my_entity() const;

protected:
  ai_goal *owner;
  int flags;
  unsigned int id;
};

class anim_ai_action : public ai_action
{
public:
  virtual bool frame_advance(float);
  virtual void going_out_of_service();
  virtual void going_into_service();

protected:
  stringx anim_to_find;
  stringx sound_grp;
  int anim_slot;
  bool looping;
  bool reverse;
  bool non_cosmetic;
  bool tween;
  int anim_damage_value;
  rational_t anim_recover;
  rational_t anim_recover_var;
  int anim_flags;
  vector3d safe_pos;
  bool safety_checks;
};

enum
{
  ANIM_RELATIVE_TO_START = 0x0001,
  ANIM_REVERSE = 0x0002,
  ANIM_LOOPING = 0x0004,
  ANIM_AUTOKILL = 0x0008,
  ANIM_NONCOSMETIC = 0x0200,
  ANIM_TWEEN = 0x0800
};

void anim_ai_action::going_into_service()
{
  ai_action::going_into_service();

  get_ai_interface()->play_animation(anim_to_find, anim_slot, (ANIM_RELATIVE_TO_START | ANIM_AUTOKILL | (tween ? ANIM_TWEEN : 0) | (non_cosmetic ? ANIM_NONCOSMETIC : 0) | (looping ? ANIM_LOOPING : 0) | (reverse ? ANIM_REVERSE : 0)), &anim_damage_value, &anim_recover, &anim_recover_var, &anim_flags);

  if(safety_checks)
  {
    vector3d hit_loc;
    if(get_my_entity()->get_primary_region() != 0 && in_world(get_my_entity()->get_abs_position(), 0.25f, ZEROVEC, get_my_entity()->get_primary_region(), hit_loc))
    {
      safety_checks = true;
      safe_pos = get_my_entity()->get_abs_position();
    }
    else
      safety_checks = false;
  }
}
